1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
xfrm: iptfs: validate inner IPv4 header length in IPTFS
 payload

Add validation of the inner IPv4 packet tot_len and ihl fields parsed
from decrypted IPTFS payloads in __input_process_payload(). A crafted
ESP packet containing an inner IPv4 header with tot_len=0 causes an
infinite loop: iplen=0 leads to capturelen=min(0, remaining)=0, so the
data offset never advances and the while(data < tail) loop never
terminates, spinning forever in softirq context.

Reject inner IPv4 packets where tot_len < ihl*4 or ihl*4 < sizeof(struct
iphdr), which catches both the tot_len=0 case and malformed ihl values.
The normal IP stack performs this validation in ip_rcv_core(), but IPTFS
extracts and processes inner packets before they reach that layer.

Reported-by: Roshan Kumar <roshaen09@gmail.com>
Fixes: 6c82d2433671 ("xfrm: iptfs: add basic receive packet (tunnel egress) handling")
Cc: stable@vger.kernel.org
Signed-off-by: Roshan Kumar <roshaen09@gmail.com>
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>

Here is the root cause:
The bug is an infinite loop in `__input_process_payload()` when processing a crafted ESP packet containing an inner IPv4 header with `tot_len = 0`. The code extracts `iplen` and `iphlen` from the inner IPv4 header and computes `capturelen = min(iplen, remaining)`. With `iplen = 0`, `capturelen` becomes 0, which causes the data offset pointer `data` to never advance past the current position. As a result, the `while(data < tail)` loop runs indefinitely without consuming any payload, leading to a spin in softirq context. The root cause is the absence of validation for the inner IPv4 header fields (`tot_len` and `ihl`) before they are used, preventing early rejection of malformed packets.

Here is the patch:

 static bool __input_process_payload(struct xfrm_state *x, u32 data,
 				    struct skb_seq_state *skbseq,
 				    struct list_head *sublist)
 {
 	u8 hbytes[sizeof(struct ipv6hdr)];
 	struct iptfs_skb_frag_walk _fragwalk;
 	struct iptfs_skb_frag_walk *fragwalk = NULL;
 	struct sk_buff *defer, *first_skb, *next, *skb;
 	const unsigned char *old_mac;
 	struct xfrm_iptfs_data *xtfs;
 	struct iphdr *iph;
 	struct net *net;
 	u32 first_iplen, iphlen, iplen, remaining, tail;
 	u32 capturelen;
 	u64 seq;

 	xtfs = x->mode_data;
 	net = xs_net(x);
 	skb = skbseq->root_skb;
 	first_skb = NULL;
 	defer = NULL;

 	seq = __esp_seq(skb);

 	/* Save the old mac header if set */
 	old_mac = skb_mac_header_was_set(skb) ? skb_mac_header(skb) : NULL;

 	/* New packets */

 	tail = skb->len;
 	while (data < tail) {
 		__be16 protocol = 0;

 		/* Gather information on the next data block.
 		 * `data` points to the start of the data block.
 		 */
 		remaining = tail - data;

 		/* try and copy enough bytes to read length from ipv4/ipv6 */
 		iphlen = min_t(u32, remaining, 6);
 		if (skb_copy_seq_read(skbseq, data, hbytes, iphlen)) {
 			XFRM_INC_STATS(net, LINUX_MIB_XFRMINBUFFERERROR);
 			goto done;
 		}

 		iph = (struct iphdr *)hbytes;
 		if (iph->version == 0x4) {
 			/* must have at least tot_len field present */
 			if (remaining < 4) {
 				/* save the bytes we have, advance data and exit */
 				iptfs_input_save_runt(xtfs, seq, hbytes,
 						      remaining);
 				data += remaining;
 				break;
 			}

 			iplen = be16_to_cpu(iph->tot_len);
 			iphlen = iph->ihl << 2;
+			if (iplen < iphlen || iphlen < sizeof(*iph)) {
+				XFRM_INC_STATS(net,
+					       LINUX_MIB_XFRMINHDRERROR);
+				goto done;
+			}
 			protocol = cpu_to_be16(ETH_P_IP);
 			XFRM_MODE_SKB_CB(skbseq->root_skb)->tos = iph->tos;
 		} else if (iph->version == 0x6) {
 			/* must have at least payload_len field present */
 			if (remaining < 6) {
 				/* save the bytes we have, advance data and exit */
 				iptfs_input_save_runt(xtfs, seq, hbytes,
 						      remaining);
 				data += remaining;
 				break;
 			}

 			iplen = be16_to_cpu(((struct ipv6hdr *)hbytes)->payload_len);
 			iplen += sizeof(struct ipv6hdr);
 			iphlen = sizeof(struct ipv6hdr);
 			protocol = cpu_to_be16(ETH_P_IPV6);
 			XFRM_MODE_SKB_CB(skbseq->root_skb)->tos =
 				ipv6_get_dsfield((struct ipv6hdr *)iph);
 		} else if (iph->version == 0x0) {
 			/* pad */
 			data = tail;
 			break;
 		} else {
 			XFRM_INC_STATS(net, LINUX_MIB_XFRMINBUFFERERROR);
 			goto done;
 		}

 		if (unlikely(skbseq->stepped_offset)) {
 			/* We need to reset our seq read, it can't backup at
 			 * this point.
 			 */
 			struct sk_buff *save = skbseq->root_skb;

 			skb_abort_seq_read(skbseq);
 			skb_prepare_seq_read(save, data, tail, skbseq);
 		}

 		if (first_skb) {
 			skb = NULL;
 		} else {
 			first_skb = skb;
 			first_iplen = iplen;
 			fragwalk = NULL;

 			/* We are going to skip over `data` bytes to reach the
 			 * start of the IP header of `iphlen` len for `iplen`
 			 * inner packet.
 			 */

 			if (skb_has_frag_list(skb)) {
 				defer = skb;
 				skb = NULL;
 			} else if (data + iphlen <= skb_headlen(skb) &&
 				   /* make sure our header is 32-bit aligned? */
 				   /* ((uintptr_t)(skb->data + data) & 0x3) == 0 && */
 				   skb_tailroom(skb) + tail - data >= iplen) {
 				/* Reuse the received skb.
 				 *
 				 * We have enough headlen to pull past any
 				 * initial fragment data, leaving at least the
 				 * IP header in the linear buffer space.
 				 *
 				 * For linear buffer space we only require that
 				 * linear buffer space is large enough to
 				 * eventually hold the entire reassembled
 				 * packet (by including tailroom in the check).
 				 *
 				 * For non-linear tailroom is 0 and so we only
 				 * re-use if the entire packet is present
 				 * already.
 				 *
 				 * NOTE: there are many more options for
 				 * sharing, KISS for now. Also, this can produce
 				 * skb's with the IP header unaligned to 32
 				 * bits. If that ends up being a problem then a
 				 * check should be added to the conditional
 				 * above that the header lies on a 32-bit
 				 * boundary as well.
 				 */
 				skb_pull(skb, data);

 				/* our range just changed */
 				data = 0;
 				tail = skb->len;
 				remaining = skb->len;

 				skb->protocol = protocol;
 				skb_mac_header_rebuild(skb);
 				if (skb->mac_len)
 					eth_hdr(skb)->h_proto = skb->protocol;

 				/* all pointers could be changed now reset walk */
 				skb_abort_seq_read(skbseq);
 				skb_prepare_seq_read(skb, data, tail, skbseq);
 			} else if (skb->head_frag &&
 				   /* We have the IP header right now */
 				   remaining >= iphlen) {
 				fragwalk = &_fragwalk;
 				iptfs_skb_prepare_frag_walk(skb, data, fragwalk);
 				defer = skb;
 				skb = NULL;
 			} else {
 				/* We couldn't reuse the input skb so allocate a
 				 * new one.
 				 */
 				defer = skb;
 				skb = NULL;
 			}

 			/* Don't trim `first_skb` until the end as we are
 			 * walking that data now.
 			 */
 		}

 		capturelen = min(iplen, remaining);
 		if (!skb) {
 			if (!fragwalk ||
 			    /* Large enough to be worth sharing */
 			    iplen < IPTFS_PKT_SHARE_MIN ||
 			    /* Have IP header + some data to share. */
 			    capturelen <= iphlen ||
 			    /* Try creating skb and adding frags */
 			    !(skb = iptfs_pskb_add_frags(first_skb, fragwalk,
 							 data, capturelen,
 							 skbseq, iphlen))) {
 				skb = iptfs_pskb_extract_seq(iplen, skbseq, data, capturelen);
 			}
 			if (!skb) {
 				/* skip to next packet or done */
 				data += capturelen;
 				continue;
 			}

 			skb->protocol = protocol;
 			if (old_mac) {
 				/* rebuild the mac header */
 				skb_set_mac_header(skb, -first_skb->mac_len);
 				memcpy(skb_mac_header(skb), old_mac, first_skb->mac_len);
 				eth_hdr(skb)->h_proto = skb->protocol;
 			}
 		}

 		data += capturelen;

 		if (skb->len < iplen) {
 			/* Start reassembly */
 			spin_lock(&xtfs->drop_lock);

 			xtfs->ra_newskb = skb;
 			xtfs->ra_wantseq = seq + 1;
 			if (!hrtimer_is_queued(&xtfs->drop_timer)) {
 				/* softirq blocked lest the timer fire and interrupt us */
 				hrtimer_start(&xtfs->drop_timer,
 					      xtfs->drop_time_ns,
 					      IPTFS_HRTIMER_MODE);
 			}

 			spin_unlock(&xtfs->drop_lock);

 			break;
 		}

 		iptfs_complete_inner_skb(x, skb);
 		list_add_tail(&skb->list, sublist);
 	}

 	if (data != tail)
 		/* this should not happen from the above code */
 		XFRM_INC_STATS(net, LINUX_MIB_XFRMINIPTFSERROR);

 	if (first_skb && first_iplen && !defer && first_skb != xtfs->ra_newskb) {
 		/* first_skb is queued b/c !defer and not partial */
 		if (pskb_trim(first_skb, first_iplen)) {
 			/* error trimming */
 			list_del(&first_skb->list);
 			defer = first_skb;
 		}
 		first_skb->ip_summed = CHECKSUM_NONE;
 	}

 	/* Send the packets! */
 	list_for_each_entry_safe(skb, next, sublist, list) {
 		skb_list_del_init(skb);
 		if (xfrm_input(skb, 0, 0, -2))
 			kfree_skb(skb);
 	}
 done:
 	skb = skbseq->root_skb;
 	skb_abort_seq_read(skbseq);

 	if (defer) {
 		consume_skb(defer);
 	} else if (!first_skb) {
 		/* skb is the original passed in skb, but we didn't get far
 		 * enough to process it as the first_skb, if we had it would
 		 * either be save in ra_newskb, trimmed and sent on as an skb or
 		 * placed in defer to be freed.
 		 */
 		kfree_skb(skb);
 	}
 	return true;
 }



